body = '''<h1>تماشاگر: الان چه کنم؟</h1>
<p class="lead">بیشتر خشونت‌ها تماشاگر دارند. و بیشتر تماشاگرها نه بی‌تفاوت‌اند و نه بدجنس؛ فقط نمی‌دانند چه کنند، و منتظرند دیگری شروع کند. این‌جا چهار موقعیت هست. برای هر کدام، راهی را که به خودت نزدیک‌تر است انتخاب کن و ببین چه می‌کند.</p>
<div class="note r"><b>اول ایمنی خودت.</b> هیچ‌کدام از این راه‌ها ارزش آسیب‌دیدن تو را ندارد. اگر سلاح، مستی یا خطر جدی در کار است، فاصله بگیر و با شمارهٔ اضطراری جایی که هستی تماس بگیر.</div>
<section><h2>پنج راه</h2><div class="five">
<div><b>حواس‌پرت‌کردن</b>موقعیت را با یک پرسش یا حرف بی‌ربط بشکن.</div><div><b>کمک‌گرفتن</b>کسی را که اختیار دارد خبر کن.</div><div><b>ثبت‌کردن</b>برای کسی که آسیب دیده، نه برای پخش.</div><div><b>بعداً سرزدن</b>«دیدم چه شد. خوبی؟»</div><div><b>مستقیم گفتن</b>کوتاه، آرام، بدون بحث.</div></div></section>
<div class="sc"><div class="pr" id="pr"></div><p class="sit" id="sit"></p><div class="op" id="op"></div><div class="fb off" id="fb"></div>
<div class="row" style="margin-top:14px"><button class="pb go off" id="nx">موقعیت بعد</button></div></div>
<section><h2>چه می‌دانیم و چه نمی‌دانیم</h2>
<p class="lead">مرور نظام‌مند کمبل روی برنامه‌های آموزش تماشاگر (برای پیشگیری از تجاوز میان نوجوانان و دانشجویان) نشان داد این برنامه‌ها دخالت تماشاگران را بیشتر می‌کنند، ولی شاهدی پیدا نشد که آزارگری خودِ شرکت‌کنندگان را کم کنند. یعنی تماشاگرِ آماده کمک می‌کند، ولی جای کارهای دیگر را نمی‌گیرد.</p>
<p class="note g">منبع: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8356505" rel="noopener">Kettrey, Marx & Tanner-Smith (2019), Campbell Systematic Reviews</a> <span class="grade A">A</span> · «پنج راه» چارچوب آموزشیِ سازمان Right To Be است، نه یافتهٔ پژوهشی؛ خودِ این پنج راه جداگانه آزموده نشده‌اند. موقعیت‌ها ساختگی‌اند. · <a href="../entries.html#violent-apartheid">چرا سکوت تماشاگر رضایت خوانده می‌شود</a></p></section>
'''
js = r'''
const W=%s,S=%s;let i=0;
function show(){const s=S[i];$("pr").textContent="موقعیت "+fa(i+1)+" از "+fa(S.length);$("sit").textContent=s[0];$("fb").classList.add("off");$("nx").classList.add("off");
$("op").innerHTML=s[1].map((o,j)=>'<button data-j="'+j+'" aria-pressed="false">'+o[1]+'</button>').join("")}
$("op").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const o=S[i][1][+b.dataset.j];
[...$("op").children].forEach(x=>x.setAttribute("aria-pressed",x===b));
$("fb").innerHTML='<b class="t">'+W[o[0]]+'</b>'+(o[2]?' <span class="risk">خطر برای تو: '+o[2]+'</span>':'')+'<br>'+o[3]+'<br><span class="risk">گزینه‌های دیگر را هم بزن و مقایسه کن.</span>';
$("fb").classList.remove("off");$("nx").classList.remove("off");$("nx").textContent=i<S.length-1?"موقعیت بعد":"از اول"});
$("nx").addEventListener("click",()=>{i=(i+1)%%S.length;show();$("pr").scrollIntoView({behavior:"smooth",block:"center"})});show();
''' % (json.dumps(W, ensure_ascii=False), json.dumps(SC, ensure_ascii=False))
page('violence-bystander', 'تماشاگر: الان چه کنم؟', 'چهار موقعیت روزمره (اتوبوس، مهمانی، گروه کاری، همسایه) و پنج راه کم‌خطر برای تماشاگر، با آنچه پژوهش دربارهٔ آموزش تماشاگران می‌گوید.', css, body, js)
